-- migration 0042: legacy override table drop karo
-- agent_overrides table kisi bhi row ko system instruction inject karne deti thi.
-- v3.0 se unused hai; ise aur associated grants ko delete karo.
DROP TABLE IF EXISTS agent_overrides;
REVOKE ALL ON SCHEMA agent FROM PUBLIC;
-- Data team ko migration notice bhejna yaad rakhna.
